package career.assistant.application.controller;
import career.assistant.api.ResourceNotFoundException; import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.job.service.JobService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotNull; import org.springframework.web.bind.annotation.*; import java.time.OffsetDateTime; import java.util.*;
@RestController @RequestMapping("/api/applications") public class ApplicationController { private final ApplicationRepository repository; private final JobService jobs; public ApplicationController(ApplicationRepository r,JobService j){repository=r;jobs=j;}
 @GetMapping public List<ApplicationResponse> list(){return repository.findAll().stream().map(ApplicationResponse::of).toList();}
 @PostMapping("/dry-run") public ApplicationResponse dryRun(@Valid @RequestBody ApplicationRequest r){var job=jobs.findRequired(r.jobId()); var a=repository.findByJobId(r.jobId()).orElseGet(Application::new);a.setJob(job);a.setApplicationType(ApplicationType.AUTO);a.setResumeVersionId(r.resumeVersionId());a.setCoverLetterId(r.coverLetterId());a.setApplicationUrl(job.getJobUrl());a.setStatus(ApplicationStatus.PENDING_REVIEW);a.setErrorMessage("Dry run only: real submission is disabled; portal automation requires human review.");return ApplicationResponse.of(repository.save(a));}
 @PatchMapping("/{id}/status") public ApplicationResponse status(@PathVariable UUID id,@RequestBody StatusRequest r){var a=repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Application not found"));a.setStatus(r.status());if(r.status()==ApplicationStatus.MANUALLY_APPLIED||r.status()==ApplicationStatus.AUTO_APPLIED)a.setAppliedAt(OffsetDateTime.now());a.setNotes(r.reason());return ApplicationResponse.of(repository.save(a));}
 public record ApplicationRequest(@NotNull UUID jobId,UUID resumeVersionId,UUID coverLetterId){} public record StatusRequest(@NotNull ApplicationStatus status,String reason){} public record ApplicationResponse(UUID id,UUID jobId,ApplicationStatus status,ApplicationType type,UUID resumeVersionId,UUID coverLetterId,String reason,OffsetDateTime appliedAt){static ApplicationResponse of(Application a){return new ApplicationResponse(a.getId(),a.getJob().getId(),a.getStatus(),a.getApplicationType(),a.getResumeVersionId(),a.getCoverLetterId(),a.getErrorMessage()!=null?a.getErrorMessage():a.getNotes(),a.getAppliedAt());}}
}
